{"text":"/// writes `worker`/`worktree`/`workflow`, which are separate tokens and unaffected.
const STOP_WORDS: &[&str] = &[
    // articles, prepositions, conjunctions
    "the", "a", "an", "to", "for", "in", "is", "are", "and", "or", "of", "with", "on", "it", "at",
    "as", "by", "from", "about", "into", // demonstratives / pronouns
    "this", "that", "these", "those", "my", "me", "i", "we", "you", "your", "its", "there",
    // auxiliary / modal verbs (#837)
    "do", "does", "did", "done", "be", "been", "being", "am", "was", "were", "has", "have", "had",
    "can", "could", "should", "would", "will", "shall", "may", "might", "must",
    // interrogatives (#837)
    "how", "what", "where", "when", "why", "who", "whom", "which",
    // generic verbs of operation — see the doc comment above for the `work` decision (#837)
    "work", "works", "working",
];

/// Tokenize a natural-language query into keywords.
///
/// Splits on whitespace, lowercases, filters out common stop words, and
/// decomposes any snake_case/camelCase tokens into component words.
fn tokenize_query(query: &str) -> Vec<String> {
    let mut keywords = Vec::new();
    for word in query.split_whitespace() {
        // Decompose from the original casing (so camelCase boundaries are visible)
        let parts = decompose_identifier(word);
        if parts.len() > 1 {
            for part in parts {
                if !STOP_WORDS.contains(&part.as_str()) {
                    keywords.push(part);
                }
            }
        } else {
            // Single word or no decomposition — just lowercase and filter
            let lower = word.to_lowercase();
            if !STOP_WORDS.contains(&lower.as_str()) {
                keywords.push(lower);
            }
        }
    }
    keywords
}

