{"text":"//! `/revisit` command handler — review closed/shelved issues that may now be feasible.
//!
//! Subcommands:
//! - `scan` (default): fetch recently closed issues and show candidates for revisiting
//! - `check #N`: inspect a specific closed issue and summarize what changed since closure
//! - `list`: show issues previously marked as revisit candidates (from `.yoyo/revisit.json`)
//! - `add #N <reason>`: mark a closed issue as a revisit candidate
//! - `remove #N`: remove an issue from the revisit list

use crate::format::*;
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::Path;
use std::process::Command;

/// File where revisit candidates are persisted.
const REVISIT_FILE: &str = ".yoyo/revisit.json";

/// Labels that indicate an issue was shelved rather than truly resolved.
const SHELVED_LABELS: &[&str] = &[
    "wontfix",
    "deferred",
    "too-complex",
    "won't fix",
    "later",
    "shelved",
    "backlog",
];

/// Subcommands for `/revisit`.
pub const REVISIT_SUBCOMMANDS: &[&str] = &["scan", "check", "list", "add", "remove"];

/// A revisit candidate persisted to `.yoyo/revisit.json`.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct RevisitCandidate {
    pub number: u64,
    pub title: String,
    pub reason: String,
    pub added_day: u64,
}

/// A closed issue fetched from GitHub.
#[derive(Debug, Clone)]
pub struct ClosedIssue {
    pub number: u64,
    pub title: String,
    pub labels: Vec<String>,
    pub closed_at: String,
}

/// Parse the contents of a revisit file.
///
/// Pure: no I/O, so the three states are testable without touching disk.
/// An empty (or whitespace-only) file is `Ok(vec![])` — a zero-byte file has no
/// surviving entries to lose. Anything else that isn't a valid candidate list is
/// an `Err` carrying the serde message, never a silent empty list (#740).
fn parse_revisit_file(content: &str) -> Result<Vec<RevisitCandidate>, String> {
    if content.trim().is_empty() {
        return Ok(Vec::new());
    }
    serde_json::from_str(content).map_err(|e| e.to_string())
}

/// Load revisit candidates from a specific path.
///
/// Three distinct states, kept distinct: a missing file is `Ok(vec![])`
/// (genuinely empty is not an error), while an unreadable or unparseable file is
/// an `Err` naming the path and what went wrong. Callers that write must refuse
/// to write on `Err` — the old `unwrap_or_default()` turned a damaged file into
/// an empty list, and the next `/revisit add` overwrote every surviving entry
/// under a green success message (#740).
fn load_revisit_list_from(path: &Path) -> Result<Vec<RevisitCandidate>, String> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let display = path.display();
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Could not read revisit file {display}: {e}"))?;
    parse_revisit_file(&content)
        .map_err(|e| format!("Revisit file {display} is not valid revisit JSON: {e}"))","citations":["https://github.com/yologdev/yoyo-evolve/blob/7bcb8caa94e8ae0816cee7b8235012f551edc94c/src/commands_revisit.rs#L1"]}

